using OcctSharp.IntersectionResults;
using OcctSharp.CopiedCollections;
using OcctSharp.Tests.Shared;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed class IntersectionResultTests {
 [Fact]public void TangentSurfaceIsolatedPointRetainsBothUvCoordinates(){using var spherical=BatchBHIntersectionWorkflow.Spherical();using var face=BatchBHIntersectionWorkflow.Horizontal(2);using var plane=RayIntersections.CopySurface(face);using var result=SurfaceIntersections.Compute(spherical,plane);Assert.True(result.IsDone);Assert.Empty(result.Lines);Assert.Single(result.Points);var point=result.Points[0];Assert.Equal(2,point.Point.Z,7);foreach(var p in new[]{BatchBHIntersectionWorkflow.Eval(spherical,point.FirstUv.X,point.FirstUv.Y),BatchBHIntersectionWorkflow.Eval(plane,point.SecondUv.X,point.SecondUv.Y)})Assert.InRange(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,point.Point.X,point.Point.Y,point.Point.Z),0,1e-6);var points=result.Points;result.Dispose();Assert.Single(points);}
 [Fact]public void RestrictedSplineIntersectionRetainsSdkLineClassificationAndLifetime(){using var first=GeomBSplineSurfaceCollections.Create(new([new Coordinates3d(0,0,0),new(0,2,0),new(2,0,0),new(2,2,0)],2,2),new([0.0,1]),new([0.0,1]),new([2,2]),new([2,2]),1,1,false,false);using var second=GeomBSplineSurfaceCollections.Create(new([new Coordinates3d(0,0,0),new(0,2,0),new(0,0,2),new(0,2,2)],2,2),new([0.0,1]),new([0.0,1]),new([2,2]),new([2,2]),1,1,false,false);using var result=SurfaceIntersections.Compute(first,second);Assert.True(result.IsDone);Assert.Equal(0,result.BoundaryCount);Assert.Throws<ArgumentOutOfRangeException>(()=>result.CopyBoundary(1));Assert.Single(result.Lines);using var line=result.CopyLine(1);result.Dispose();first.Dispose();second.Dispose();var p=line.Curve.Value(.5);Assert.InRange(Math.Abs(p.X)+Math.Abs(p.Z),0,1e-6);Assert.InRange(p.Y,0,2);}
 [Fact]public void CoupledGeometryFiniteHitsTopologyAndActualFileReadback()=>BatchBHIntersectionWorkflow.Run();
 [Fact]public void FiniteRayHasOrderedExactFacesAndIndependentLifetime(){using var box=ShapeFactory.CreateBox(2,2,2);using var result=RayIntersections.Line(box,new(-1,1,1),new(2,0,0),0,5);Assert.True(result.IsDone);Assert.Equal(2,result.Hits.Count);Assert.Equal(new[]{1.0,3},result.Hits.Select(x=>x.Parameter));foreach(var h in result.Hits){Assert.Equal(0,h.State);Assert.Equal(h.Parameter-1,h.Point.X,10);using var face=result.CopyFace(h.FaceOrdinal);Assert.Equal(ShapeKind.Face,face.Kind);var p=SurfaceModeling.Evaluate(face,new(h.U,h.V)).Point;Assert.InRange(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,h.Point.X,h.Point.Y,h.Point.Z),0,1e-7);}using var independent=result.CopyFace(result.Hits[0].FaceOrdinal);var hits=result.Hits;box.Dispose();result.Dispose();Assert.True(independent.IsValid);Assert.Equal(2,hits.Count);Assert.Throws<ObjectDisposedException>(()=>result.CopyFace(hits[0].FaceOrdinal));}
 [Fact]public void NoHitsAndFiniteSubintervalAreDistinctCompletedResults(){using var box=ShapeFactory.CreateBox(2,2,2);using var none=RayIntersections.Line(box,new(-1,5,5),new(1,0,0),0,5);Assert.True(none.IsDone);Assert.Empty(none.Hits);using var one=RayIntersections.Line(box,new(-1,1,1),new(1,0,0),0,2,maximumHits:1);Assert.True(one.IsDone);Assert.Single(one.Hits);Assert.Equal(1,one.Hits[0].Parameter,10);Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(-1,1,1),new(1,0,0),0,5,maximumHits:1));}
 [Fact]public void BoundaryAndEqualParameterHitsRemainSeparate(){using var first=ShapeFactory.CreateBox(2,2,2);using var second=ShapeFactory.CreateBox(2,2,2);using var compound=ShapeFactory.CreateCompound([first,second]);using var equal=RayIntersections.Line(compound,new(-1,1,1),new(1,0,0),0,5);Assert.True(equal.IsDone);Assert.Equal(4,equal.Hits.Count);Assert.Equal(new[]{1.0,1,3,3},equal.Hits.Select(x=>x.Parameter));Assert.Equal(equal.Hits.OrderBy(x=>x.Parameter).ThenBy(x=>x.SdkOrdinal),equal.Hits);using var boundary=RayIntersections.Line(first,new(-1,0,0),new(1,0,0),0,5);Assert.True(boundary.IsDone);Assert.NotEmpty(boundary.Hits);Assert.All(boundary.Hits,x=>Assert.Equal(2,x.State));}
 [Fact]public void TangentAndPeriodicSeamHitsRetainNativeUvTransition(){using var sphere=ShapeFactory.CreateSphere(2);using var tangent=RayIntersections.Line(sphere,new(-3,2,0),new(1,0,0),0,6);Assert.True(tangent.IsDone);Assert.NotEmpty(tangent.Hits);Assert.Contains(tangent.Hits,x=>x.Transition==0);using var seam=RayIntersections.Line(sphere,new(3,0,0),new(-1,0,0),0,6);Assert.True(seam.IsDone);Assert.Equal(2,seam.Hits.Count);foreach(var h in seam.Hits){using var face=seam.CopyFace(h.FaceOrdinal);var p=SurfaceModeling.Evaluate(face,new(h.U,h.V)).Point;Assert.InRange(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,h.Point.X,h.Point.Y,h.Point.Z),0,1e-6);}}
 [Fact]public void FiniteSplineQueryCopiesCurveAndUsesCurveParameters(){using var box=ShapeFactory.CreateBox(2,2,2);using var curve=GeomBSplineCurveCollections.Create(new(new Coordinates3d[]{new(-1,1,1),new(3,1,1)}),new([0.0,1]),new([2,2]),1,false);using var result=RayIntersections.Curve(box,curve,0,1);Assert.True(result.IsDone);Assert.Equal(2,result.Hits.Count);Assert.Equal(.25,result.Hits[0].Parameter,8);Assert.Equal(.75,result.Hits[1].Parameter,8);curve.Dispose();box.Dispose();using var copied=result.CopyFace(result.Hits[0].FaceOrdinal);Assert.True(copied.IsValid);}
 [Fact]public void InvalidRayAndFaceOccurrenceBudgetsFailBeforePublication(){using var box=ShapeFactory.CreateBox(2,2,2);Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(0,0,0),new(0,0,0),0,1));Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(0,0,0),new(1,0,0),0,double.PositiveInfinity));Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(0,0,0),new(1,0,0),2,1));Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(0,0,0),new(1,0,0),0,1,tolerance:0));Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(box,new(0,0,0),new(1,0,0),0,1,maximumHits:4097));var faces=box.GetFaces();try{using var many=ShapeFactory.CreateCompound(Enumerable.Repeat(faces[0],257).ToArray());Assert.ThrowsAny<Exception>(()=>RayIntersections.Line(many,new(0,0,0),new(1,0,0),0,1));}finally{foreach(var face in faces)face.Dispose();}}
 [Fact]public void SurfaceLinesPreserveMissingPcurvesWithoutReconstruction(){using var a=BatchBHIntersectionWorkflow.Horizontal();using var b=BatchBHIntersectionWorkflow.Vertical();using var first=RayIntersections.CopySurface(a);using var second=RayIntersections.CopySurface(b);using var result=SurfaceIntersections.Compute(first,second,new(PCurveOnFirst:false,PCurveOnSecond:false));Assert.True(result.IsDone);Assert.Single(result.Lines);Assert.False(result.Lines[0].HasFirstPCurve);Assert.False(result.Lines[0].HasSecondPCurve);using var line=result.CopyLine(1);Assert.Null(line.FirstPCurve);Assert.Null(line.SecondPCurve);Assert.ThrowsAny<Exception>(()=>result.BoundaryParameters(1,new(-1,1,-1,1),new(-1,1,-1,1)));}
 [Fact]public void ExplicitPcurveConstructionMatchesIndependentSurfaceEvaluation(){using var a=BatchBHIntersectionWorkflow.Horizontal();using var b=BatchBHIntersectionWorkflow.Vertical();using var first=RayIntersections.CopySurface(a);using var second=RayIntersections.CopySurface(b);using var result=SurfaceIntersections.Compute(first,second);using var line=result.CopyLine(1);foreach(bool bounded in new[]{false,true}){using var built=SurfaceIntersections.BuildPCurve(first,line.Curve,0,1,bounds:bounded?new(-100,100,-100,100):null);Assert.True(double.IsFinite(built.ReachedTolerance));foreach(double t in new[]{0.0,.5,1}){var p=line.Curve.Value(t);var uv=BatchBHIntersectionWorkflow.Eval(built.Curve,t);var q=BatchBHIntersectionWorkflow.Eval(first,uv.X,uv.Y);Assert.InRange(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,q.X,q.Y,q.Z),0,1e-6);}}Assert.ThrowsAny<Exception>(()=>SurfaceIntersections.BuildPCurve(first,line.Curve,1,0));Assert.ThrowsAny<Exception>(()=>SurfaceIntersections.BuildPCurve(first,line.Curve,0,1,bounds:new(1,0,0,1)));}
 [Fact]public void CoupledTrimParametersAndCopiesHaveIndependentLifetime(){using var a=BatchBHIntersectionWorkflow.Horizontal(.5);using var first=BatchBHIntersectionWorkflow.Spherical();using var second=RayIntersections.CopySurface(a);using var result=SurfaceIntersections.Compute(first,second);var parameters=result.BoundaryParameters(1,new(.2,1,-1,1),new(-5,5,-5,5));Assert.NotEmpty(parameters);Assert.All(parameters,x=>Assert.True(double.IsFinite(x)));using var line=result.CopyLine(1);using var source=result.CopySourceSurface(0);result.Dispose();first.Dispose();second.Dispose();Assert.True(double.IsFinite(line.Curve.Value(0).X));Assert.True(double.IsFinite(BatchBHIntersectionWorkflow.Eval(source,0,0).X));Assert.Throws<ObjectDisposedException>(()=>result.CopyLine(1));}
 [Fact]public void ParallelSurfacesCompleteWithoutLinesAndBudgetsAreEnforced(){using var a=BatchBHIntersectionWorkflow.Horizontal();using var b=BatchBHIntersectionWorkflow.Horizontal(3);using var first=RayIntersections.CopySurface(a);using var second=RayIntersections.CopySurface(b);using var result=SurfaceIntersections.Compute(first,second);Assert.True(result.IsDone);Assert.Empty(result.Lines);Assert.Empty(result.Points);Assert.Equal(0,result.BoundaryCount);Assert.ThrowsAny<Exception>(()=>SurfaceIntersections.Compute(first,second,new(Tolerance:0)));using var vertical=BatchBHIntersectionWorkflow.Vertical();using var cross=RayIntersections.CopySurface(vertical);Assert.ThrowsAny<Exception>(()=>SurfaceIntersections.Compute(first,cross,new(MaximumResults:0)));Assert.Throws<ArgumentOutOfRangeException>(()=>result.CopyLine(1));}
 [Fact]public void PeriodicSpherePlaneIntersectionPreservesCoupledUvBranches(){using var sphere=ShapeFactory.CreateSphere(2);var faces=sphere.GetFaces();try{using var spherical=RayIntersections.CopySurface(faces[0]);using var face=BatchBHIntersectionWorkflow.Horizontal(.5);using var plane=RayIntersections.CopySurface(face);using var result=SurfaceIntersections.Compute(spherical,plane);Assert.True(result.IsDone);Assert.NotEmpty(result.Lines);foreach(var info in result.Lines){using var line=result.CopyLine(info.Ordinal);Assert.NotNull(line.FirstPCurve);Assert.NotNull(line.SecondPCurve);double first=info.Parameters.First!.Value,last=info.Parameters.Last!.Value;Assert.True(double.IsFinite(first)&&double.IsFinite(last)&&last>first);for(int i=1;i<8;++i){double t=first+(last-first)*i/8;var p=line.Curve.Value(t);var uv=BatchBHIntersectionWorkflow.Eval(line.FirstPCurve!,t);var q=BatchBHIntersectionWorkflow.Eval(spherical,uv.X,uv.Y);Assert.InRange(BatchBHIntersectionWorkflow.Distance(p.X,p.Y,p.Z,q.X,q.Y,q.Z),0,1e-5);}}}finally{foreach(var face in faces)face.Dispose();}}
}
